const query = input.query || '';

let response = {
  agent: agentConfig.name,
  intent: intent,
  success: true
};

switch (intent) {
  case 'help':
    response.content = `# ${agentConfig.name} Agent Help\n\n## Available Commands\n\n| Intent | Description |\n|--------|-------------|\n| help | Show this help message |\n| status | Check knowledge base status |\n| list | List documents in knowledge base |\n| upload | Upload a document to knowledge base |\n| reload | Reload all documents in knowledge base |\n| query | Query the knowledge base |\n\n## Knowledge Base\n- Collection: ${agentConfig.collectionName}\n- Folder: ${agentConfig.folder}\n\n## Solution Domains\n- Solution Design Patterns\n- Integration Architecture\n- Deployment Architecture\n- Scalability Planning\n`;
    response.message = `${agentConfig.name} Help`;
    break;

  case 'status':
    response.action = 'query_qdrant_status';
    response.collection = agentConfig.collectionName;
    break;

  case 'list':
    response.action = 'query_qdrant_list';
    response.collection = agentConfig.collectionName;
    break;

  case 'upload':
    response.action = 'call_knowledge_loader';
    response.loaderPayload = {
      action: 'upload',
      collection: agentConfig.collectionName,
      folder: agentConfig.folder,
      content: input.content || '',
      filename: input.filename || ''
    };
    break;

  case 'reload':
    response.action = 'call_knowledge_loader';
    response.loaderPayload = {
      action: 'reload',
      collection: agentConfig.collectionName,
      folder: agentConfig.folder
    };
    break;

  case 'query':
    response.action = 'rag_query';
    response.collection = agentConfig.collectionName;
    response.query = query;
    break;

  default:
    response.success = false;
    response.errorMessage = `Unknown intent: ${intent}. Valid intents: help, status, list, upload, reload, query`;
}

return [{ json: response }];

